function resolveCommentFileReference(value, ticketKey, workingDir) {
    if (typeof value !== 'string') return null;
    var trimmed = value.trim();
    if (!/^(outputs\/)?(pr_review_comments\/)?[\w.\-]+\.md$/.test(trimmed)) {
